import{c as e,Q as o,j as a,m as l}from"./chunks/framework.DOi4mjdC.js";const c="/assets/%E6%9C%80%E4%BD%B3%E5%AE%9E%E8%B7%B5%E4%BC%98%E5%8C%96Reduce%E4%BD%BF%E7%94%A8%E7%AB%A0%E8%8A%82-61.D2LeSimA.png",s="/assets/%E6%9C%80%E4%BD%B3%E5%AE%9E%E8%B7%B5%E4%BC%98%E5%8C%96Reduce%E4%BD%BF%E7%94%A8%E7%AB%A0%E8%8A%82-62.BcGBebuX.png",r="/assets/%E6%9C%80%E4%BD%B3%E5%AE%9E%E8%B7%B5%E4%BC%98%E5%8C%96Reduce%E4%BD%BF%E7%94%A8%E7%AB%A0%E8%8A%82-63.RV8_Pneh.png",q=JSON.parse('{"title":"设置合理的L2 CacheMode","description":"","frontmatter":{},"headers":[{"level":1,"title":"设置合理的L2 CacheMode","slug":"设置合理的l2-cachemode"},{"level":2,"title":"L2 Cache访问的原理及CacheMode介绍","slug":"l2-cache访问的原理及cachemode介绍"},{"level":2,"title":"设置L2 CacheMode的方法","slug":"设置l2-cachemode的方法"}],"relativePath":"guide/算子实践参考/SIMD算子性能优化/内存访问/设置合理的L2-CacheMode.md","filePath":"guide/算子实践参考/SIMD算子性能优化/内存访问/设置合理的L2-CacheMode.md"}'),p={name:"guide/算子实践参考/SIMD算子性能优化/内存访问/设置合理的L2-CacheMode.md"};function d(u,t,h,g,i,n){return o(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="设置合理的l2-cachemode" tabindex="-1">设置合理的L2 CacheMode <a class="header-anchor" href="#设置合理的l2-cachemode" aria-label="Permalink to &quot;设置合理的L2 CacheMode&quot;">​</a></h1><p>【优先级】高</p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>该性能优化指导适用于如下产品型号：</p><ul><li>Ascend 950PR/Ascend 950DT</li><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li></ul></div><p>【描述】L2 Cache常用于缓存频繁访问的数据，其物理位置如下图所示：</p><p><img src="'+c+'" alt=""></p><p>L2 Cache的带宽相比GM的带宽有数倍的提升，因此当数据命中L2 Cache时，数据的搬运耗时会优化数倍。通常情况下，L2 Cache命中率越高，算子的性能越好，在实际访问中需要通过设置合理的L2 CacheMode来保证重复读取的数据尽量缓存在L2 Cache上。</p><h2 id="l2-cache访问的原理及cachemode介绍" tabindex="-1">L2 Cache访问的原理及CacheMode介绍 <a class="header-anchor" href="#l2-cache访问的原理及cachemode介绍" aria-label="Permalink to &quot;L2 Cache访问的原理及CacheMode介绍&quot;">​</a></h2><p>数据通过MTE2搬运单元搬入时，L2 Cache访问的典型流程如下：</p><p><img src="'+s+'" alt=""></p><p>数据通过MTE3或者Fixpipe搬运单元搬出时，L2 Cache访问的典型流程如下：</p><p><img src="'+r+'" alt=""></p><p>从上面的流程可以看出，当数据访问总量超出L2 Cache容量时，AI Core会对L2 Cache进行数据替换。由于Cache一致性的要求，替换过程中旧数据需要先写回GM（此过程中会占用GM带宽），旧数据写回后，新的数据才能进入L2 Cache。</p><p>开发者可以针对访问的数据设置其CacheMode，对于只访问一次的Global Memory数据设置其访问状态为不进入L2 Cache，这样可以更加高效的利用L2 Cache缓存需要重复读取的数据，避免一次性访问的数据替换有效数据。</p><h2 id="设置l2-cachemode的方法" tabindex="-1">设置L2 CacheMode的方法 <a class="header-anchor" href="#设置l2-cachemode的方法" aria-label="Permalink to &quot;设置L2 CacheMode的方法&quot;">​</a></h2><p>Ascend C基于GlobalTensor提供了SetL2CacheHint接口，用户可以根据需要指定CacheMode。</p><p>考虑如下场景，构造两个Tensor的相加计算，输入x、y和输出z的Shape均为(8192, 8192)。下文完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/04_best_practices/00_vector_compute_practices/add_high_performance" target="_blank" rel="noreferrer">设置合理L2 CacheMode样例</a>。</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.813978389954251%&quot;&gt;&lt;p&gt;实现方案&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;42.67497323079919%&quot;&gt;&lt;p&gt;原始实现&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50.51104837924658%&quot;&gt;&lt;p&gt;优化实现&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.813978389954251%&quot;&gt;&lt;p&gt;实现方法&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;42.67497323079919%&quot;&gt;&lt;p&gt;总数据量384MB，其中：x：128MB；y：128MB；z：128MB。&lt;/p&gt; &lt;p&gt;使用48个核参与计算，按行方向切分6份，列方向切分8份。&lt;/p&gt; &lt;p&gt;x、y、z 对应GlobalTensor的CacheMode均设置为CACHE_MODE_NORMAL，需要经过L2 Cache，需要进入L2 Cache的总数据量为384MB。&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50.51104837924658%&quot;&gt;&lt;p&gt;总数据量384MB，其中：x：128MB；y：128MB；z：128MB。&lt;/p&gt; &lt;p&gt;使用48个核参与计算，按行方向切分6份，列方向切分8份。&lt;/p&gt; &lt;p&gt;z对应的GlobalTensor的CacheMode设置为CACHE_MODE_NORMAL；x和y对应的GlobalTensor的CacheMode设置为CACHE_MODE_DISABLE。只将z设置为需要经过L2 Cache。需要进入L2 Cache的总数据量为128MB。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;6.813978389954251%&quot;&gt;&lt;p&gt;示例代码&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;42.67497323079919%&quot;&gt;&lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot;&gt;xGm.SetGlobalBuffer((<strong>gm</strong> half *)x + startM * totalN + startN, bufferSize); yGm.SetGlobalBuffer((<strong>gm</strong> half *)y + startM * totalN + startN, bufferSize); zGm.SetGlobalBuffer((<strong>gm</strong> half *)z + startM * totalN + startN, bufferSize);&lt;/pre&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;50.51104837924658%&quot;&gt;&lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot;&gt;xGm.SetGlobalBuffer((<strong>gm</strong> half *)x + startM * totalN + startN, bufferSize); yGm.SetGlobalBuffer((<strong>gm</strong> half *)y + startM * totalN + startN, bufferSize); zGm.SetGlobalBuffer((<strong>gm</strong> half *)z + startM * totalN + startN, bufferSize); // disable the L2 cache mode of x and y xGm.SetL2CacheHint(AscendC::CacheMode::CACHE_MODE_DISABLE); yGm.SetL2CacheHint(AscendC::CacheMode::CACHE_MODE_DISABLE);&lt;/pre&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>你可以通过执行如下命令行，通过msprof工具获取上述示例的性能数据并进行对比。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>msprof op --launch-count=2 --output=./prof ./execute_add_op</span></span></code></pre></div><p>重点关注Memory.csv中的aiv_gm_to_ub_bw(GB/s)和aiv_main_mem_write_bw(GB/s)写带宽的速率。</p></div>',18)])])}const m=e(p,[["render",d]]);export{q as __pageData,m as default};
